export const aug20BlogDetails=Object.fromEntries(specs.map((s,i)=>[s.slug,{mainKeyword:s.keyword,published:'2026-08-20',sourceDate:'2026-08-20',modified:'2026-08-20',thumbnail:`/blog-thumbnails/aug20-2026/hero-${String(i+1).padStart(2,'0')}.png`,shortAnswer:`Prepare the ${s.keyword} evidence from approved source records, then route ${s.decision} to the named owner.`,sections:makeSections(s),faqs:[{question:`What should outsourced AP support do in ${s.keyword}?`,answer:`It gathers source evidence, records gaps, and follows the documented escalation route. It does not decide ${s.decision}, alter vendor master data, approve invoices, or release payments.`}]}]));
